import { minutes } from './types.ts';
import type { BookingInput, Problem } from './types.ts';

// A rule looks at one booking request and returns a Problem, or null when it is fine.
// TODO: describe that with a function type, and use it for both rules.
export type Rule = unknown;

export const endAfterStart = (input) =>
  minutes(input.end) <= minutes(input.start) ? { code: 'END_BEFORE_START', message: 'The end must be after the start' } : null;

export const notTooLong = (input) =>
  minutes(input.end) - minutes(input.start) > 240 ? { code: 'TOO_LONG', message: 'At most 4 hours' } : null;

// LabFlow types for this exercise (given — do not edit).
export type Role = 'STUDENT' | 'LECTURER' | 'ADMIN';
export type BookingInput = { lab: string; seats: number; role: Role; start: string; end: string };
export type ProblemCode = 'OFF_GRID' | 'END_BEFORE_START' | 'OUTSIDE_HOURS' | 'TOO_LONG' | 'TOO_MANY_SEATS';
export type Problem = { code: ProblemCode; message: string };

// "08:30" -> 510
export function minutes(text: string): number {
  const [h, m] = text.split(':');
  return Number(h) * 60 + Number(m);
}

import { endAfterStart, notTooLong } from '../src/rules.ts';
import type { Rule } from '../src/rules.ts';
import type { BookingInput, Problem } from '../src/types.ts';

const fewer: Rule = () => null;                   // ignoring the input is allowed
const RULES: Rule[] = [endAfterStart, notTooLong, fewer];
const input: BookingInput = { lab: 'BE-201', seats: 45, role: 'STUDENT', start: '08:00', end: '13:00' };
const first: Problem | null = RULES[0]?.(input) ?? null;
export { first };

import type { Rule } from '../src/rules.ts';

const seatsOnly: Rule = (seats: number) => null; // expect TS2322
const text: Rule = () => 'TOO_LONG'; // expect TS2322
export { seatsOnly, text };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { endAfterStart, notTooLong } from '../src/rules.ts';

const base = { lab: 'BE-201', seats: 10, role: 'STUDENT', start: '08:00', end: '10:00' } as const;
test('08:00-10:00 passes both rules', () => {
  assert.equal(endAfterStart(base), null);
  assert.equal(notTooLong(base), null);
});
test('10:00-08:00 ends before it starts', () => assert.equal(endAfterStart({ ...base, start: '10:00', end: '08:00' })?.code, 'END_BEFORE_START'));
test('08:00-13:00 is too long', () => assert.equal(notTooLong({ ...base, end: '13:00' })?.code, 'TOO_LONG'));

