// "07,08,09,10" -> [7, 8, 9, 10]: the hours a lecturer wants to block, typed as text.
// map passes (value, index, array); parseInt would read the index as its radix. Pass exactly what we mean.
export function parseHours(text: string): number[] {
  return text.split(',').map((h) => Number.parseInt(h, 10));
}

