import { test } from 'node:test';
import assert from 'node:assert/strict';
import { validate } from '../src/validate.ts';
import type { Problem } from '../src/types.ts';

const input = { lab: 'BE-201', seats: 45, role: 'STUDENT', start: '08:00', end: '10:00' } as const;
const tooMany = (b: { seats: number }): Problem | null => (b.seats > 40 ? { code: 'TOO_MANY_SEATS', message: 'At most 40 seats' } : null);
test('collects the problems of every rule', () => assert.deepEqual(validate(input, [tooMany, () => null]).map((p) => p.code), ['TOO_MANY_SEATS']));
test('tells onProblem about each problem', () => {
  const seen: string[] = [];
  validate(input, [tooMany, tooMany], (p) => { seen.push(p.code); });
  assert.deepEqual(seen, ['TOO_MANY_SEATS', 'TOO_MANY_SEATS']);
});
